// Accept only a public web address. The node's own fetch also refuses private
// addresses, but it cannot see an internal host name, so the obvious cases are
// turned away here, with a reason the form can show.
const form = $input.first().json;
const url = String(form.url || '').trim();
// Read with plain string steps: the firewall in front of n8n's template upload
// refused this node when the same check was written as two regex matches.
const lower = url.toLowerCase();
const schemeLength = lower.startsWith('https://') ? 8 : lower.startsWith('http://') ? 7 : 0;
let problem = '';
if (!schemeLength) {
  problem = 'That is not a web address starting with http:// or https://.';
} else {
  const rest = url.slice(schemeLength);
  const end = rest.search(/[\/?#]/);
  const authority = end === -1 ? rest : rest.slice(0, end);
  const colon = authority.lastIndexOf(':');
  const host = (colon === -1 ? authority : authority.slice(0, colon)).toLowerCase();
  const port = colon === -1 ? '' : authority.slice(colon + 1);
  const digitsOnly = (s) => s.length > 0 && s.split('').every((c) => c >= '0' && c <= '9');
  if (authority.includes('@')) problem = 'Addresses with a user name in them are not accepted.';
  else if (!host || host.includes(':') || host.includes('[') || host.includes(']') || (port && !digitsOnly(port))) problem = 'Only public web addresses are accepted.';
  else if (port && port !== '80' && port !== '443') problem = 'Only addresses on the standard web ports are accepted.';
  else if (host === 'localhost' || ['.localhost', '.local', '.internal', '.lan', '.home'].some((t) => host.endsWith(t)) ||
    host.split('').every((c) => c === '.' || (c >= '0' && c <= '9')) || !host.includes('.')) {
    problem = 'Only public web addresses are accepted.';
  }
}

// The region is added to every search, so it must stay plain words: no
// quotes, no operators, nothing that could steer the query.
const region = String(form.region || '')
  .replace(/\b(site|filetype|intitle|inurl|inbody|cache|related):\S*/gi, ' ')
  .replace(/["'()]/g, ' ')
  .replace(/(^|\s)[-+]\S*/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 40);

return [{ json: { url, ok: !problem, problem, region, today: $now.toFormat('yyyy-MM-dd'), year: Number($now.toFormat('yyyy')) } }];

// Decide whether what came back is an article worth reading. The node reports
// a failed fetch as an item with empty content and an error, not as a failed
// execution, so both have to be checked here.
const req = $('Check the request').first().json;
const page = $input.first().json;
const text = typeof page.content === 'string' ? page.content.trim() : '';

// A consent, login or bot wall passes a length check, so it is caught by what it says.
const WALL = /enable javascript|accept (all )?cookies|cookie (policy|settings|consent)|subscribe to (continue|read)|access denied|are you a robot|verify you are (a )?human|sign in to continue|log in to continue/i;

// The node reads at most 2 MB of a page; a bigger one fails with a bare
// HTTP-client code, which means nothing to the person reading the form.
const explainError = (e) => (/ERR_BAD_RESPONSE|maxContentLength/i.test(e)
  ? 'the page is larger than the 2 MB the DuckDuckGo node reads'
  : String(e).slice(0, 160));

let problem = '';
if (!text && page.error) problem = 'The article could not be read: ' + explainError(page.error) + '.';
else if (text.length < 800) problem = 'Too little readable text came back from that page. It may need JavaScript, sit behind a paywall, or not be an article.';
else if (WALL.test(text.slice(0, 800))) problem = 'The page returned a cookie, login or bot wall instead of the article.';

// The article is untrusted text: fenced with a per-run nonce so it cannot
// close its own fence and talk to the model.
const nonce = Math.random().toString(36).slice(2, 10);

return [{
  json: {
    ok: !problem,
    problem,
    url: req.url,
    region: req.region,
    year: req.year,
    today: req.today,
    title: String(page.title || '').trim().slice(0, 200),
    truncated: !!page.pageContentTruncated,
    nonce,
    text,
    fenced: '<<<ARTICLE ' + nonce + '>>>\n' + text + '\n<<<END ARTICLE ' + nonce + '>>>',
  },
}];

// Keep a figure only when code can confirm what the model said about it: the
// sentence is really in the article, the value really is in the sentence, and
// the year it refers to is written there too. Anything else is dropped with a
// reason, and the reasons are shown to the user.
const art = $('Check the article').first().json;
const output = $input.first().json.output || {};
const proposed = Array.isArray(output.figures) ? output.figures : [];

const norm = (s) => String(s || '').toLowerCase()
  .replace(/[‘’‛]/g, "'").replace(/[“”‟]/g, '"')
  .replace(/[–—−]/g, '-').replace(/ /g, ' ').replace(/\s+/g, ' ').trim();
// Whole numbers only: "5" must not match inside "2025", nor "12" inside "112".
const numbers = (s) => (String(s || '').match(/\d[\d,]*(?:\.\d+)?/g) || []).map((t) => Number(t.replace(/,/g, '')));
const years = (s) => (String(s || '').match(/\b(19[5-9]\d|20\d\d)\b/g) || []).map(Number);
const FORECAST = /\b(will|would|expected to|projected|projection|forecasts?|predicted|estimated to reach|target|by (19|20)\d\d)\b/i;
const unitKind = (s) => {
  const t = String(s || '').toLowerCase();
  if (/percentage points?|\bpp\b|\bpts?\b/.test(t)) return 'points';
  if (/%|per ?cent/.test(t)) return 'percent';
  if (/[$€£¥]|\b(usd|eur|gbp|dollars?|euros?|pounds?|yen)\b/.test(t)) return 'money';
  return 'count';
};
const clean = (s) => String(s || '').replace(/["'()]/g, ' ').replace(/\s+/g, ' ').trim();

const article = norm(art.text);
const kept = [];
const dropped = [];
const seen = new Set();
for (const f of proposed) {
  const sentence = String((f && f.sentence) || '').trim();
  const value = String((f && f.value) || '').trim();
  const year = Number(f && f.year);
  // Only the stated year is set aside: a value such as 2,000 people is a value,
  // not a year, even though it looks like one.
  const valueNumbers = numbers(value).filter((n) => n !== year);
  const words = sentence.split(/\s+/).filter(Boolean).length;
  let reason = '';
  if (!sentence || !article.includes(norm(sentence))) reason = 'the sentence is not in the article as quoted';
  else if (words < 5 || words > 80) reason = 'the sentence is too short or too long to check';
  else if (!valueNumbers.length || !valueNumbers.every((n) => numbers(sentence).includes(n))) reason = 'the value is not in the sentence';
  else if (FORECAST.test(sentence)) reason = 'it is a forecast or target, not a measured figure';
  else if (!Number.isInteger(year) || !years(sentence).includes(year)) reason = 'the sentence does not say which year the figure is for';
  else if (year > art.year - 1) reason = 'the figure is for this year or later';
  const key = norm(f && f.metric) + '|' + norm(f && f.scope);
  if (!reason && seen.has(key)) reason = 'the same measure appears earlier';
  if (reason) { dropped.push({ sentence: sentence.slice(0, 300), reason }); continue; }
  seen.add(key);
  if (kept.length >= 5) { dropped.push({ sentence: sentence.slice(0, 300), reason: 'only five figures are checked per run' }); continue; }
  kept.push({
    figure: true,
    index: kept.length + 1,
    sentence,
    value,
    valueNumbers,
    unitKind: unitKind(value + ' ' + String((f && f.unit) || '')),
    metric: String((f && f.metric) || '').trim().slice(0, 160),
    scope: String((f && f.scope) || '').trim().slice(0, 120),
    year,
    searchQuery: (clean(f && f.search_query) + ' ' + art.region).trim().slice(0, 140),
  });
}

if (!kept.length) {
  return [{ json: { figure: false, proposed: proposed.length, dropped } }];
}
// The drop list travels with every item, so the report can show it.
return kept.map((k) => ({ json: Object.assign(k, { proposed: proposed.length, dropped }) }));

// Always returns exactly one item for the figure, whatever the search did, so
// a figure can never silently drop out of the report.
const fig = $('Loop over figures').first().json;
const results = $input.all().map((i) => i.json);

const failure = results.find((r) => r.error);
const blocked = !!failure && /challenge|bot-detection|back-off|not sent|rate.?limit|too many requests/i.test(String(failure.error));

// Text that is a page's furniture rather than its content passes a length
// check, so it is caught by what it says.
const WALL = /enable javascript|accept (all )?cookies|cookie (policy|settings|consent)|subscribe to (continue|read)|access denied|are you a robot|verify you are (a )?human/i;

const sources = [];
for (const r of results) {
  if (!r.url || r.error) continue;
  const content = typeof r.pageContent === 'string' ? r.pageContent.trim() : '';
  const garbled = (content.match(/�/g) || []).length > content.length * 0.01;
  const isPage = !r.pageContentError && content.length >= 400 && !garbled && !WALL.test(content.slice(0, 800));
  // The Code node's sandbox has no URL class, so the host is read directly.
  const hostMatch = /^https?:\/\/([^\/?#:@]+)/i.exec(String(r.url));
  if (!hostMatch) continue;
  const host = hostMatch[1].toLowerCase().replace(/^www\./, '');
  // Only a page that was actually read can back a figure: the table promises
  // each quote is word for word on its source page, and a search snippet can
  // be cut short, out of date, or missing from the page it links to.
  if (!isPage) continue;
  const text = content;
  sources.push({
    title: String(r.pageTitle || r.title || host).slice(0, 200),
    url: r.url,
    host,
    published: r.pagePublished || null,
    kind: 'page',
    text,
  });
}

let status = 'searched';
if (blocked) status = 'blocked';
else if (!sources.length) status = 'nothing_readable';

return [{ json: { figure: fig, status, error: failure ? String(failure.error) : null, sources } }];

// Every page read becomes S1, S2... in code, so the model can only point at a
// source that exists and never writes a URL. Page text is untrusted and is
// fenced with a per-run nonce.
const art = $('Check the article').first().json;
const graded = $input.all().map((i) => i.json).sort((a, b) => a.figure.index - b.figure.index);

const canonical = (url) => {
  const m = /^https?:\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?/i.exec(String(url));
  if (!m) return String(url).toLowerCase();
  return (m[1].replace(/^www\./i, '') + m[2].replace(/\/+$/, '') + (m[3] || '')).toLowerCase();
};

const byKey = new Map();
const sources = [];
const figures = graded.map((g) => {
  const ids = [];
  for (const s of g.sources) {
    const key = canonical(s.url);
    let source = byKey.get(key);
    if (!source) {
      source = Object.assign({ id: 'S' + (sources.length + 1) }, s);
      byKey.set(key, source);
      sources.push(source);
    }
    if (!ids.includes(source.id)) ids.push(source.id);
  }
  return Object.assign({}, g.figure, { status: g.status, error: g.error, sourceIds: ids });
});

const nonce = Math.random().toString(36).slice(2, 10);
const evidence = sources.map((s) => [
  '<<<SOURCE ' + s.id + ' ' + nonce + '>>>',
  'Title: ' + s.title,
  'Site: ' + s.host + (s.published ? ' (published ' + s.published + ')' : ''),
  'Text:',
  s.text,
  '<<<END ' + s.id + ' ' + nonce + '>>>',
].join('\n')).join('\n\n');

const list = figures.map((f) => 'F' + f.index + '. "' + f.sentence + '"\n   measure: ' + f.metric +
  (f.scope ? ' | scope: ' + f.scope : '') + ' | value: ' + f.value + ' | year: ' + f.year +
  '\n   sources: ' + (f.sourceIds.length ? f.sourceIds.join(', ') : 'none')).join('\n');

return [{ json: { title: art.title, url: art.url, year: art.year, today: art.today, truncated: art.truncated, figures, sources, list, evidence, searchable: sources.length > 0 } }];

