// A candidate is shown only if code can confirm it: the quote is really in a
// source found for that figure, the new value and a later year are both in
// the quote and close together, and it is not a forecast. What code cannot
// confirm - that it measures the same thing - is left to the reader, with a
// warning when the units plainly differ.
const bundle = $('Number the sources').first().json;
const output = $input.first().json.output || {};
const proposed = Array.isArray(output.candidates) ? output.candidates : [];

const norm = (s) => String(s || '').toLowerCase()
  .replace(/[‘’‛]/g, "'").replace(/[“”‟]/g, '"')
  .replace(/[–—−]/g, '-').replace(/ /g, ' ').replace(/…/g, '')
  .replace(/\.\.\.$/, '').replace(/\s+/g, ' ').trim();
const numberTokens = (s) => {
  const out = [];
  const re = /\d[\d,]*(?:\.\d+)?/g;
  let m;
  while ((m = re.exec(String(s || '')))) out.push({ n: Number(m[0].replace(/,/g, '')), at: m.index });
  return out;
};
const FORECAST = /\b(will|would|expected to|projected|projection|forecasts?|predicted|estimated to reach|target|by (19|20)\d\d)\b/i;
const unitKind = (s) => {
  const t = String(s || '').toLowerCase();
  if (/percentage points?|\bpp\b|\bpts?\b/.test(t)) return 'points';
  if (/%|per ?cent/.test(t)) return 'percent';
  if (/[$€£¥]|\b(usd|eur|gbp|dollars?|euros?|pounds?|yen)\b/.test(t)) return 'money';
  return 'count';
};

const byId = new Map(bundle.sources.map((s) => [s.id, s]));
const byIndex = new Map(bundle.figures.map((f) => [f.index, f]));
const accepted = new Map();
let rejected = 0;

for (const c of proposed) {
  const fig = byIndex.get(Number(c && c.figure));
  const source = byId.get(String((c && c.source_id) || '').trim());
  const quote = String((c && c.quote) || '').trim();
  const value = String((c && c.value) || '').trim();
  const year = Number(c && c.year);
  const words = quote.split(/\s+/).filter(Boolean).length;
  const inQuote = numberTokens(quote);
  // Only the stated year is set aside, so a value such as 2,000 still counts.
  const valueNumbers = numberTokens(value).map((t) => t.n).filter((n) => n !== year);
  const valueHits = inQuote.filter((t) => valueNumbers.includes(t.n));
  const yearHits = inQuote.filter((t) => t.n === year);
  const close = valueHits.some((v) => yearHits.some((y) => Math.abs(v.at - y.at) <= 80));
  const ok = fig && source && source.kind === 'page' && fig.sourceIds.includes(source.id) &&
    words >= 8 && words <= 60 &&
    norm(source.text).includes(norm(quote)) &&
    valueNumbers.length > 0 && valueNumbers.every((n) => valueHits.some((t) => t.n === n)) &&
    Number.isInteger(year) && year > fig.year && year <= bundle.year && close &&
    !FORECAST.test(quote);
  if (!ok) { rejected += 1; continue; }
  // One candidate per figure: the latest year wins.
  const prev = accepted.get(fig.index);
  if (prev && prev.year >= year) continue;
  const kind = unitKind(value + ' ' + quote.slice(Math.max(0, valueHits[0].at - 3), valueHits[0].at + 30));
  accepted.set(fig.index, {
    sourceId: source.id,
    quote,
    value,
    year,
    unchanged: valueNumbers.length === fig.valueNumbers.length && valueNumbers.every((n, i) => n === fig.valueNumbers[i]),
    differentUnit: kind !== fig.unitKind,
  });
}

const rows = bundle.figures.map((f) => Object.assign({}, f, { candidate: accepted.get(f.index) || null }));
return [{ json: { rows, rejected, found: accepted.size } }];

// The review table, built here as HTML from data. Nothing written by the
// article, a source page or the model is rendered as markup: every string is
// escaped, and the only links are source addresses that start with http(s).
const bundle = $('Number the sources').first().json;
const checks = $input.first().json;
const dropped = ($('Check the figures').first().json.dropped) || [];
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const byId = new Map(bundle.sources.map((s) => [s.id, s]));
const link = (s) => (/^https?:\/\//i.test(s.url)
  ? '<a href="' + esc(s.url) + '" target="_blank" rel="noopener noreferrer nofollow">' + esc(s.title || s.host) + '</a>'
  : esc(s.title || s.host));

const rows = checks.rows.map((r) => {
  const old = '<blockquote>' + esc(r.sentence) + '</blockquote>' +
    '<p class="meta">' + esc(r.metric) + (r.scope ? ' &middot; ' + esc(r.scope) : '') + ' &middot; <b>' + esc(r.value) + '</b> for ' + esc(r.year) + '</p>';
  let found;
  if (r.candidate) {
    const c = r.candidate;
    const s = byId.get(c.sourceId);
    const notes = [];
    if (c.unchanged) notes.push('Same value as the article.');
    if (c.differentUnit) notes.push('Different unit from the article&#39;s figure: probably a different measure.');
    found = '<blockquote>' + esc(c.quote) + '</blockquote>' +
      '<p class="meta"><b>' + esc(c.value) + '</b> for ' + esc(c.year) + ' &middot; ' + link(s) + ' (' + esc(s.host) + ')</p>' +
      (notes.length ? '<p class="warn">' + notes.join(' ') + '</p>' : '');
  } else if (r.status === 'blocked') {
    found = '<p class="none">Not checked: DuckDuckGo blocked this search.</p>';
  } else {
    found = '<p class="none">No later-dated figure found in ' + r.sourceIds.length + ' page' + (r.sourceIds.length === 1 ? '' : 's') + ' read.</p>';
  }
  return '<tr><td>' + old + '</td><td>' + found + '</td></tr>';
}).join('');

const droppedList = dropped.length
  ? '<details><summary>' + dropped.length + ' figure' + (dropped.length === 1 ? '' : 's') + ' not checked</summary><ul>' +
    dropped.map((d) => '<li>' + esc(d.sentence) + ' <em>(' + esc(d.reason) + ')</em></li>').join('') + '</ul></details>'
  : '';

const html = '<h1>Later figures for: ' + esc(bundle.title || bundle.url) + '</h1>' +
  '<p class="lead">Checked ' + esc(bundle.today) + '. <b>' + checks.found + ' of ' + checks.rows.length +
  '</b> dated figures have a later-dated figure next to them. These are candidates for review, not corrections: ' +
  'a quote shown here is word for word on its source page, but that does not prove the figure is right or that it measures the same thing. ' +
  'Compare the two sentences before you edit.</p>' +
  (bundle.truncated ? '<p class="warn">The article was longer than the part that was read; figures near its end were not checked.</p>' : '') +
  '<table><thead><tr><th>In the article</th><th>Later-dated figure</th></tr></thead><tbody>' + rows + '</tbody></table>' +
  droppedList +
  '<p class="foot">Tables and charts are not read: figures that appear only there are not checked.</p>';

return [{ json: { html } }];

// One page for every way a run can end without a table: the address was not
// accepted, the article could not be read, or it held no dated figure that
// could be checked. Each says what happened and what to try.
const input = $input.first().json;
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

let heading = 'Nothing to check';
let body = '';
if (input.figure === false) {
  heading = 'No dated figures to check';
  const dropped = input.dropped || [];
  body = '<p>' + (input.proposed
    ? input.proposed + ' figure' + (input.proposed === 1 ? ' was' : 's were') + ' found, but none could be checked:'
    : 'The article does not state any figure together with the year it refers to.') + '</p>' +
    (dropped.length ? '<ul>' + dropped.map((d) => '<li>' + esc(d.sentence) + ' <em>(' + esc(d.reason) + ')</em></li>').join('') + '</ul>' : '') +
    '<p>Only figures whose sentence names the year they refer to are checked, and forecasts are left out.</p>';
} else {
  heading = 'This article could not be checked';
  body = '<p>' + esc(input.problem || 'The page could not be read.') + '</p>' +
    '<p>Try the address of the article itself rather than a home or listing page.</p>';
}
const html = '<h1>' + esc(heading) + '</h1>' + body +
  '<p class="foot">Each run makes up to five DuckDuckGo searches, and DuckDuckGo limits searches per IP address, so leave a few minutes between runs.</p>';
return [{ json: { html } }];
